export function deriveEfficiencyMetrics(t) { const executionCost = t.modelCalls * 5 + t.toolCalls + t.delegations * 4 + t.retries * 3 + t.verificationActions * 2 + t.humanInteractions * 4 + Math.ceil(t.contextChars / 4000); return { executionCost, wastedComputeRatio: t.totalActions ? Math.max(0, (t.totalActions - t.productiveActions) / t.totalActions) : 0, humanAttentionEfficiency: t.humanInteractions ? t.materialHumanDecisions / t.humanInteractions : 1, contextEfficiency: t.contextChars ? Math.min(1, t.decisionRelevantContextChars / t.contextChars) : 1 }; }
